import {
  type ClientInterface,
  Membership,
  type RoomInfo,
  type RoomInterface,
  type SyncServiceInterface,
} from "@unomed/react-native-matrix-sdk";
import { MatrixJotaiStore } from "../const/matrx-jotai-store";
import { MatrixAtoms } from "../jotai";

export class MatrixCore {
  public static instance: ClientInterface | null = null;
  public static syncService: SyncServiceInterface | null = null;

  /** Returns the client or throws if not initialized. Eliminates per-method null checks. */
  public static getClient(): ClientInterface {
    if (!MatrixCore.instance) {
      throw new Error("Matrix client is not initialized");
    }
    return MatrixCore.instance;
  }

  /** Returns the room or throws. Use instead of getClient().getRoom() + manual null check. */
  public static getRoom(roomId: string): RoomInterface {
    const room = MatrixCore.getClient().getRoom(roomId);
    if (!room) throw new Error(`Room not found: ${roomId}`);
    return room;
  }

  public static getServerName = () => {
    if (!MatrixCore.instance) return null;
    return MatrixCore.instance.server() || MatrixCore.instance.homeserver();
  };

  /** Sort and store the current room list into Jotai. Called after any membership change. */
  public static refreshRoomList = async () => {
    if (!MatrixCore.instance) return;

    try {
      const rooms = MatrixCore.instance.rooms();

      const sortedRooms = await Promise.all(
        rooms.map(async (room) => ({
          room,
          timestamp: (await room.latestEvent())?.timestamp || 0,
        })),
      );

      const filteredAndSortedRooms = sortedRooms
        .filter(({ room }) => {
          const membership = room.membership();
          return (
            membership !== Membership.Banned &&
            membership !== Membership.Left &&
            membership !== Membership.Knocked
          );
        })
        .sort((a, b) => {
          const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
          const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
          if (aInvited !== bInvited) return bInvited - aInvited;
          return Number(b.timestamp) - Number(a.timestamp);
        });

      MatrixJotaiStore.set(
        MatrixAtoms.roomList,
        filteredAndSortedRooms.map(({ room }) => room),
      );

      const roomInfoEntries = await Promise.allSettled(
        filteredAndSortedRooms.map(async ({ room }) => ({
          id: room.id(),
          info: await room.roomInfo(),
        })),
      );

      const map = new Map<string, RoomInfo>();
      for (const result of roomInfoEntries) {
        if (result.status === "fulfilled") {
          map.set(result.value.id, result.value.info);
        }
      }
      MatrixJotaiStore.set(MatrixAtoms.roomInfoMap, map);
    } catch (error) {
      console.error("Failed to refresh room list:", error);
    }
  };
}

