      filename: string;
    };
    editRoom: {
      room: RoomInterface;
    };
    setUpRecoveryKey: { initialKey?: string } | undefined;
    settings: undefined;
    verifyUser: {
      userId: string;
      /** If provided, this is an incoming verification request that needs to be acknowledged */
      flowId?: string;
    };
    profile: {
      userId: string;
      initialProfile?: {
        userId: string;
        displayName?: string;
        avatarUrl?: string;
      };
    };
    serverSelect: undefined;
    serverInfo: undefined;
    userProfile: undefined;
    notifications: undefined;
    notificationsIntro: undefined;
    screenLock: undefined;
    screenLockSettings: undefined;
    forwardMessage: {
      currentRoomId: string;
    };
