      roomId: string;
    };
    blockedUsers: {
      blockedUserIds: string[];
    };
    setupScreenLock: undefined;
    verifyPin: undefined;
    encryption: undefined;
    about: undefined;
    reportProblem: undefined;
    roomDetails: { room: RoomInterface };
    roomNotifications: { roomId: string };
    roomMembers: {
      roomId: string;
    };
    roomMedia: {
      room: RoomInterface;
    };
    confirmIdentity: undefined;
    cantConfirm: undefined;
    oidcResetWebView: { url: string };
    enterRecoveryKey: undefined;
    verifyWithDevice: undefined;
    notificationsType: {
      type: "group" | "direct";
      notificationsType: RoomNotificationMode;
    };
    pinnedEvents: {
      room: RoomInterface;
    };
    roomRoles: {
      room: RoomInterface;
      userPowerLevel: number;
    };
    manageRole: {
      room: RoomInterface;
      targetLevel: 50 | 100;
    };
    roomPermissions: {
      room: RoomInterface;
      userPowerLevel: number;
    };
    roomSecurity: {
      room: RoomInterface;
    };
    deactivateAccount: undefined;
  };
}

