import { MMKV } from "react-native-mmkv";

const mmkv = new MMKV({ id: "secure-client-storage" });

const KEYS = {
  ACCESS_TOKEN: "access_token",
  REFRESH_TOKEN: "refresh_token",
  USER_ID: "user_id",
  DEVICE_ID: "device_id",
  BASE_URL: "base_url",
} as const;

type Credentials = {
  accessToken: string;
  refreshToken?: string;
  userId: string;
  deviceId: string;
  baseUrl: string;
};

export const SecureClientStorage = {
  save: (credentials: Credentials) => {
    mmkv.set(KEYS.ACCESS_TOKEN, credentials.accessToken);
    mmkv.set(KEYS.USER_ID, credentials.userId);
    mmkv.set(KEYS.DEVICE_ID, credentials.deviceId);
    mmkv.set(KEYS.BASE_URL, credentials.baseUrl);
    if (credentials.refreshToken) {
      mmkv.set(KEYS.REFRESH_TOKEN, credentials.refreshToken);
    }
  },

  get: (): Credentials | null => {
    const accessToken = mmkv.getString(KEYS.ACCESS_TOKEN);
    const userId = mmkv.getString(KEYS.USER_ID);
    const deviceId = mmkv.getString(KEYS.DEVICE_ID);
    const baseUrl = mmkv.getString(KEYS.BASE_URL);
    const refreshToken = mmkv.getString(KEYS.REFRESH_TOKEN);

    if (!accessToken || !userId || !deviceId || !baseUrl) return null;

    return { accessToken, userId, deviceId, baseUrl, refreshToken };
  },

  clear: () => {
    mmkv.delete(KEYS.ACCESS_TOKEN);
    mmkv.delete(KEYS.REFRESH_TOKEN);
    mmkv.delete(KEYS.USER_ID);
    mmkv.delete(KEYS.DEVICE_ID);
    mmkv.delete(KEYS.BASE_URL);
  },

  has: () => !!SecureClientStorage.get(),
};

