import {
  BackupDownloadStrategy,
  ClientBuilder,
  type ClientInterface,
  SlidingSyncVersion,
  SlidingSyncVersionBuilder,
  type SyncServiceInterface,
} from "@unomed/react-native-matrix-sdk";
import RNFS from "react-native-fs";
import { MatrixStorage } from "../../matrix-client/const";
import { SecureClientStorage } from "../storage/SecureClientStorage";

export const SECURE_DEVICE_ID = "cloak-device-1";

const dataPath = `${RNFS.DocumentDirectoryPath}/matrix/secure/data`;
const cachePath = `${RNFS.CachesDirectoryPath}/matrix/secure/cache`;

export class SecureClientService {
  public static instance: ClientInterface | null = null;
  public static syncService: SyncServiceInterface | null = null;

  public static getClient(): ClientInterface {
    if (!SecureClientService.instance) {
      throw new Error("Secure client is not initialized");
    }
    return SecureClientService.instance;
  }

  private static initialize = async (homeserverUrl: string) => {
    SecureClientService.instance = await new ClientBuilder()
      .serverNameOrHomeserverUrl(homeserverUrl)
      .sessionPaths(dataPath, cachePath)
      .autoEnableCrossSigning(true)
      .autoEnableBackups(false)
      .backupDownloadStrategy(BackupDownloadStrategy.AfterDecryptionFailure)
      .build();
  };

  private static initializeForRestore = async (
    homeserverUrl: string,
    userId: string,
  ) => {
    SecureClientService.instance = await new ClientBuilder()
      .homeserverUrl(homeserverUrl)
      .username(userId)
      .slidingSyncVersionBuilder(SlidingSyncVersionBuilder.Native)
      .sessionPaths(dataPath, cachePath)
      .autoEnableCrossSigning(true)
      .autoEnableBackups(false)
      .backupDownloadStrategy(BackupDownloadStrategy.AfterDecryptionFailure)
      .build();
  };

  /**
   * Login with the same user credentials as the primary session, but with
   * SECURE_DEVICE_ID as the device ID. Persists the resulting session.
   * Requires the user's password (the primary session doesn't store it).
   */
  public static login = async (password: string): Promise<void> => {
    const primaryCredentials = MatrixStorage.getLoginCredentials();
    if (!primaryCredentials) throw new Error("No primary session found");

    await SecureClientService.initialize(primaryCredentials.baseUrl);
    const client = SecureClientService.getClient();

    await client.login(
      primaryCredentials.userId,
      password,
      "Cloak Device 1",
      SECURE_DEVICE_ID,
    );

    const session = client.session();
    if (!session) throw new Error("Login succeeded but session is null");

    SecureClientService.instance = null;

    SecureClientStorage.save({
      accessToken: session.accessToken,
      refreshToken: session.refreshToken ?? undefined,
      userId: session.userId,
      deviceId: session.deviceId,
      baseUrl: session.homeserverUrl,
    });

    await SecureClientService.restoreSession();
  };

  /**
   * Restore a previously created secure session from storage.
   * Returns false if no credentials are stored.
   */
  public static restoreSession = async (): Promise<boolean> => {
    const credentials = SecureClientStorage.get();
    if (!credentials) return false;

    try {
      await SecureClientService.initializeForRestore(
        credentials.baseUrl,
        credentials.userId,
      );

      const client = SecureClientService.getClient();

      await client.restoreSession({
        accessToken: credentials.accessToken,
        refreshToken: credentials.refreshToken,
        userId: credentials.userId,
        deviceId: credentials.deviceId,
        homeserverUrl: credentials.baseUrl,
        oidcData: undefined,
        slidingSyncVersion: SlidingSyncVersion.Native,
      });

      SecureClientService.syncService = await client
        .syncService()
        .withOfflineMode()
        .finish();

      if (!SecureClientService.syncService) {
        throw new Error("Failed to initialize secure sync service");
      }

      await SecureClientService.syncService.start();

      return true;
    } catch (error) {
      console.warn("[SecureClient] Failed to restore session:", error);
      SecureClientService.instance = null;
      SecureClientService.syncService = null;
      return false;
    }
  };

  public static stop = async (): Promise<void> => {
    if (SecureClientService.syncService) {
      try {
        await SecureClientService.syncService.stop();
      } catch {}
    }
    SecureClientService.instance = null;
    SecureClientService.syncService = null;
  };

  public static hasStoredSession = (): boolean =>
    SecureClientStorage.has();
}

