import { Block, Text } from "@prototyp/skeletor";
import { type RoomInterface } from "@unomed/react-native-matrix-sdk";
import { format, isThisWeek, isToday, isYesterday } from "date-fns";
import { getLastMessageType } from "modules/matrix-client/utils";
import { type FC, useEffect, useState } from "react";
import { Image, StyleSheet } from "react-native";
import { RoomImage } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { type EventTimelineItem } from "@unomed/react-native-matrix-sdk";

interface Props {
  room: RoomInterface;
}

const formatTimestamp = (timestamp: bigint | undefined) => {
  if (!timestamp) return "";
  const date = new Date(Number(timestamp));
  if (isToday(date)) return format(date, "HH:mm");
  if (isYesterday(date)) return "Yesterday";
  if (isThisWeek(date)) return format(date, "EEEE");
  return format(date, "d. M. yyyy.");
};

export const SecureRoomListItem: FC<Props> = ({ room }) => {
  const [lastMessage, setLastMessage] = useState<
    EventTimelineItem | undefined
  >(undefined);

  useEffect(() => {
    room.latestEvent().then(setLastMessage).catch(console.error);
  }, [room]);

  return (
    <Block
      flexDirection="row"
      align="center"
      paddings={[16, 20]}
      gap={12}
      border={{ borderBottomWidth: 1, borderColor: Colors.white10 }}
    >
      <RoomImage room={room} width={32} height={32} />
      <Block flex={1}>
        <Block flexDirection="row" align="center" gap={8}>
          <Image
            source={require("assets/icons/lock.png")}
            style={styles.lockIcon}
            tintColor={Colors.success}
          />
          <Text size={TextSize.base} color={Colors.success}>
            {room.displayName()}
          </Text>
        </Block>
        <Text size={TextSize.tiny} color={Colors.white50} numberOfLines={1}>
          {getLastMessageType(lastMessage)}
        </Text>
      </Block>
      {lastMessage?.timestamp && (
        <Text size={TextSize.tiny} color={Colors.white50}>
          {formatTimestamp(lastMessage.timestamp)}
        </Text>
      )}
    </Block>
  );
};

const styles = StyleSheet.create({
  lockIcon: {
    width: 12,
    height: 12,
  },
});

