import { Block, Text } from "@prototyp/skeletor";
import { FlashList, type ListRenderItem } from "@shopify/flash-list";
import { type RoomInterface } from "@unomed/react-native-matrix-sdk";
import { SecureClientService } from "modules/secure-client/service/SecureClientService";
import { type FC, useCallback, useEffect, useRef, useState } from "react";
import {
  ActivityIndicator,
  StyleSheet,
  TextInput,
  TouchableOpacity,
} from "react-native";
import { ScreenLayout } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { SecureRoomListItem } from "./fragments";

type Status = "loading" | "needs-setup" | "ready" | "error";

export const SecureChats: FC = () => {
  const [status, setStatus] = useState<Status>("loading");
  const [rooms, setRooms] = useState<RoomInterface[]>([]);
  const [password, setPassword] = useState("");
  const [isLoggingIn, setIsLoggingIn] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    bootstrap();

    return () => {
      isMounted.current = false;
      SecureClientService.stop();
    };
  }, []);

  const bootstrap = async () => {
    if (SecureClientService.hasStoredSession()) {
      const restored = await SecureClientService.restoreSession();
      if (!isMounted.current) return;

      if (restored) {
        loadRooms();
        setStatus("ready");
      } else {
        setStatus("error");
        setErrorMessage("Failed to restore secure session.");
      }
    } else {
      setStatus("needs-setup");
    }
  };

  const loadRooms = () => {
    try {
      const client = SecureClientService.getClient();
      setRooms(client.rooms());
    } catch {
      setRooms([]);
    }
  };

  const handleLogin = async () => {
    if (!password.trim()) return;
    setIsLoggingIn(true);
    setErrorMessage(null);

    try {
      await SecureClientService.login(password);
      if (!isMounted.current) return;
      loadRooms();
      setStatus("ready");
    } catch (err) {
      if (!isMounted.current) return;
      setErrorMessage("Login failed. Check your password and try again.");
    } finally {
      if (isMounted.current) {
        setIsLoggingIn(false);
        setPassword("");
      }
    }
  };

  const keyExtractor = useCallback((item: RoomInterface) => item.id(), []);

  const renderItem = useCallback<ListRenderItem<RoomInterface>>(
    ({ item }) => <SecureRoomListItem room={item} />,
    [],
  );

  return (
    <ScreenLayout paddings={{ paddingHorizontal: 0 }}>
      <Block
        flexDirection="row"
        align="center"
        margins={[40, 0, 16, 0]}
        paddings={[0, 20]}
      >
        <Text size={TextSize.large}>Secure Chats</Text>
        <Text size={TextSize.tiny} color={Colors.white50} margins={{ marginLeft: 8 }}>
          cloak-device-1
        </Text>
      </Block>

      {status === "loading" && (
        <Block flex={1} align="center" justify="center">
          <ActivityIndicator color={Colors.primary} />
        </Block>
      )}

      {status === "needs-setup" && (
        <Block paddings={[0, 20]} gap={16}>
          <Text size={TextSize.base} color={Colors.white50}>
            Enter your password to activate the secure session on this device.
          </Text>
          <TextInput
            style={styles.input}
            placeholder="Password"
            placeholderTextColor={Colors.white50}
            secureTextEntry
            value={password}
            onChangeText={setPassword}
            autoCapitalize="none"
            editable={!isLoggingIn}
          />
          {errorMessage && (
            <Text size={TextSize.tiny} color={Colors.error ?? Colors.white50}>
              {errorMessage}
            </Text>
          )}
          <TouchableOpacity
            style={[styles.button, isLoggingIn && styles.buttonDisabled]}
            onPress={handleLogin}
            disabled={isLoggingIn || !password.trim()}
          >
            {isLoggingIn ? (
              <ActivityIndicator color={Colors.white} />
            ) : (
              <Text size={TextSize.base} color={Colors.white}>
                Activate Secure Session
              </Text>
            )}
          </TouchableOpacity>
        </Block>
      )}

      {status === "error" && (
        <Block paddings={[0, 20]} gap={12}>
          <Text size={TextSize.base} color={Colors.white50}>
            {errorMessage ?? "Something went wrong."}
          </Text>
          <TouchableOpacity style={styles.button} onPress={bootstrap}>
            <Text size={TextSize.base} color={Colors.white}>
              Retry
            </Text>
          </TouchableOpacity>
        </Block>
      )}

      {status === "ready" && (
        <Block flex={1}>
          {rooms.length === 0 ? (
            <Block flex={1} align="center" justify="center" paddings={20}>
              <Text size={TextSize.base} color={Colors.white50} textAlign="center">
                No rooms found for this device.
              </Text>
            </Block>
          ) : (
            <FlashList
              data={rooms}
              keyExtractor={keyExtractor}
              renderItem={renderItem}
              estimatedItemSize={72}
            />
          )}
        </Block>
      )}
    </ScreenLayout>
  );
};

const styles = StyleSheet.create({
  input: {
    borderWidth: 1,
    borderColor: Colors.white10,
    borderRadius: 8,
    padding: 12,
    color: Colors.white,
    fontSize: 14,
  },
  button: {
    backgroundColor: Colors.primary,
    borderRadius: 8,
    padding: 14,
    alignItems: "center",
  },
  buttonDisabled: {
    opacity: 0.5,
  },
});

